/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=product, operation=getAll
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get many activities */
export type PipedriveV2ProductGetAllParams = {
  resource: 'product';
  operation: 'getAll';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2ProductGetAllOutput = {
  add_time?: string;
  billing_frequency?: string;
  billing_frequency_cycles?: unknown;
  category?: unknown;
  code?: string;
  custom_fields?: Record<string, unknown>;
  description?: string;
  id?: number;
  is_deleted?: boolean;
  is_linkable?: boolean;
  name?: string;
  owner_id?: number;
  prices?: Array<{
    cost?: number;
    currency?: string;
    direct_cost?: number;
    notes?: string;
    price?: number;
    product_id?: number;
  }>;
  tax?: number;
  unit?: string;
  update_time?: string;
  visible_to?: number;
};

export type PipedriveV2ProductGetAllNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2ProductGetAllParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2ProductGetAllOutput>;
};